8	/// The export feature's one remote data source — `export-summary-create`/
9	/// `export-status-get`, called by `x-cerne-function` name only
10	/// (AGENTS.md), [jobId] appended as [getStatus]'s one trailing path
11	/// segment. Mirrors `ChatRemoteDataSource`'s own try/catch-to-
12	/// `malformedResponse` shape for every decode step (RNF09).
13	class ExportRemoteDataSource {
14	  ExportRemoteDataSource(this._apiClient);
15	
16	  final ApiClient _apiClient;
17	
18	  /// `includeNarrative` is left unset — its own `openapi.yaml` default is
19	  /// `true`, and docs/input gives this story no reason to ever request a
20	  /// narrative-less export.
21	  ///
22	  /// Review finding (blind-hunter layer): [periodStart]/[periodEnd] arrive
23	  /// from `showDateRangePicker` as local-midnight `DateTime`s for the
24	  /// first/last *day* the user picked — sending [periodEnd] as-is (local
25	  /// midnight) would silently exclude every entry made later that same day
26	  /// from the export. Rebuilt here to the full local calendar day
27	  /// (start-of-day..end-of-day) before the one `.toUtc()` conversion, so
28	  /// the day boundary the user actually saw is preserved regardless of
29	  /// device timezone.
30	  Future<Either<Failure, String>> createJob({
31	    required DateTime periodStart,
32	    required DateTime periodEnd,
33	  }) async {
34	    final startOfDay = DateTime(
35	      periodStart.year,
36	      periodStart.month,
37	      periodStart.day,
38	    );
39	    final endOfDay = DateTime(
40	      periodEnd.year,
41	      periodEnd.month,
42	      periodEnd.day,
43	      23,
44	      59,
45	      59,
46	      999,
47	    );
48	    final result = await _apiClient.post(
49	      'export-summary-create',
50	      data: {
51	        'periodStart': startOfDay.toUtc().toIso8601String(),
52	        'periodEnd': endOfDay.toUtc().toIso8601String(),
53	      },
54	    );
55	    return result.flatMap((json) {
56	      try {
57	        final data = json['data'] as Map<String, dynamic>;
58	        return right(data['jobId'] as String);
59	      } catch (error) {
60	        return left(Failure.malformedResponse(message: error.toString()));
61	      }
62	    });
63	  }
64	
65	  Future<Either<Failure, ExportJobStatusDto>> getStatus(String jobId) async {
66	    final result = await _apiClient.get(
67	      'export-status-get',
68	      pathParams: [jobId],
69	    );
70	    return result.flatMap((json) {
71	      try {
72	        final data = json['data'] as Map<String, dynamic>;
73	        return right(ExportJobStatusDto.fromJson(data));
74	      } catch (error) {
75	        return left(Failure.malformedResponse(message: error.toString()));
76	      }
77	    });
78	  }
