82	  /// values verbatim). `ApiClient.getRedirectLocation` already owns the
83	  /// `302`-vs-error distinction (Code Map) — this is a thin pass-through,
84	  /// no mapping logic of its own.
85	  Future<Either<Failure, String>> getDownloadUrl(
86	    String jobId, {
87	    required ExportDownloadFormat format,
88	  }) => _apiClient.getRedirectLocation(
89	    'export-download-get',
90	    pathParams: [jobId],
91	    queryParameters: {'format': format.name},
92	  );
93	}
