10	class UrlLauncherDownloadOpener implements DownloadOpener {
11	  @override
12	  Future<bool> open(String url) async {
13	    try {
14	      return await launchUrl(
15	        Uri.parse(url),
16	        mode: LaunchMode.externalApplication,
17	      );
