44	  /// logic of its own.
45	  ///
46	  /// AD-3 ("reuse the existing `Failure.exportEmptyPeriod`... never add a
47	  /// new `Failure` subtype") is honored by going through the one shared
48	  /// [Failure.fromCode] for every `status: 'error'` response and then
49	  /// branching on the *subtype* it returns, rather than re-testing the
50	  /// literal `'EXPORT_EMPTY_PERIOD'` string a second time here — this
51	  /// stays correct even if a future taxonomy edit ever changed which code
52	  /// means "empty period", with no second place to update.
53	  ExportJobState toState() {
54	    switch (status) {
55	      case 'pending':
56	        return const ExportJobState.preparing();
57	      case 'processing':
58	        return const ExportJobState.generating();
59	      case 'data_ready':
60	        // spec-7-2 — its own state now: same progress-bar/text treatment
61	        // as `generating`, plus the raw-data button rendered already
62	        // enabled (`ExportJobState.dataReady`'s own doc).
63	        return const ExportJobState.dataReady();
64	      case 'done':
65	        return ExportJobState.done(
66	          narrativeStatus == 'done'
67	              ? ExportOutcome.narrativeReady
68	              : ExportOutcome.narrativeUnavailable,
69	        );
70	      case 'error':
71	        final failure = Failure.fromCode(
72	          errorCode ?? '',
73	          'Não foi possível gerar a exportação.',
74	        );
75	        return failure is ExportEmptyPeriod
76	            ? const ExportJobState.emptyPeriod()
77	            : ExportJobState.error(failure);
